def gaps(postings):
    """Convert sorted IDs to first ID followed by successive gaps."""
    return [postings[0]] + [b - a for a, b in zip(postings, postings[1:])] if postings else []

def vb_encode(n):
    """Variable byte encode an integer as a list of bytes."""
    bytes_list = []
    while True:
        bytes_list.insert(0, n % 128 + (128 if not bytes_list else 0))
        if n < 128: break
        n //= 128
    return bytes_list

def vb_encode_list(postings):
    """Flattened variable byte encoding for a list of gaps."""
    import itertools
    return list(itertools.chain.from_iterable(vb_encode(n) for n in gaps(postings)))

def vb_decode(bytes_list):
    """Decode a flat list of bytes back into the original numbers."""
    numbers, current = [], 0
    for b in bytes_list:
        if b < 128:
            current = current * 128 + b
        else:
            numbers.append(current * 128 + (b - 128))
            current = 0
    return numbers

print(vb_encode(130))

